import {
	IUIKitResponse,
	UIKitBlockInteractionContext,
} from '@rocket.chat/apps-engine/definition/uikit';
import {
	IHttp,
	IModify,
	IPersistence,
	IRead,
} from '@rocket.chat/apps-engine/definition/accessors';
import { RoomInteractionStorage } from '../storage/RoomInteraction';
import { QuickRepliesApp } from '../../QuickRepliesApp';
import { ReplyStorage } from '../storage/ReplyStorage';
import { SendReplyModal } from '../modal/sendModal';
import { Handler } from './Handler';
import { MessageActionButton, SuggestionAction } from '../enum/notification';
import { ListContextualBarEnum } from '../enum/modals/listContextualBar';
import { getUserPreferredLanguage } from '../helper/userPreference';
import { confirmDeleteModal } from '../modal/confirmDeleteModal';
import { EditReplyModal } from '../modal/editModal';
import { listReplyContextualBar } from '../modal/listContextualBar';
import { ReplyAIModalEnum } from '../enum/modals/AIreplyModal';
import { AIstorage } from '../storage/AIStorage';
import { ReplyAIModal } from '../modal/AIreplyModal';
import AIHandler from './AIHandler';
import { UserPreferenceModal } from '../modal/UserPreferenceModal';
import {
	AIProviderEnum,
	AIusagePreferenceEnum,
} from '../definition/helper/userPreference';
import { UserPreferenceModalEnum } from '../enum/modals/UserPreferenceModal';
import { UserPreferenceStorage } from '../storage/userPreferenceStorage';
import { sendMessage } from '../helper/message';

export class ExecuteBlockActionHandler {
	private context: UIKitBlockInteractionContext;
	constructor(
		protected readonly app: QuickRepliesApp,
		protected readonly read: IRead,
		protected readonly http: IHttp,
		protected readonly persistence: IPersistence,
		protected readonly modify: IModify,
		context: UIKitBlockInteractionContext,
	) {
		this.context = context;
	}

	public async handleActions(): Promise<IUIKitResponse> {
		const {
			actionId,
			user,
			container,
			blockId,
			value,
			triggerId,
			message,
		} = this.context.getInteractionData();
		let { room } = this.context.getInteractionData();
		const persistenceRead = this.read.getPersistenceReader();

		const roomInteractionStorage = new RoomInteractionStorage(
			this.persistence,
			persistenceRead,
			user.id,
		);

	const roomId = await roomInteractionStorage.getInteractionRoomId();
	const roomPersistance = roomId
	? await this.read.getRoomReader().getById(roomId)
	: undefined;

		const userPreference = new UserPreferenceStorage(
			this.persistence,
			this.read.getPersistenceReader(),
			user.id,
		);
		const existingPreference = await userPreference.getUserPreference();

		const language = await getUserPreferredLanguage(
			this.read.getPersistenceReader(),
			this.persistence,
			user.id,
		);
		const replyStorage = new ReplyStorage(
			this.persistence,
			persistenceRead,
		);
		const userReplies = await replyStorage.getReplyForUser(user);

		if (!room) {
			if (roomPersistance) {
				room = roomPersistance;
			} else {
				console.error("Room doesn't exist");
				return this.context.getInteractionResponder().errorResponse();
			}
		}
		const handler = new Handler({
			app: this.app,
			sender: user,
			room: room,
			read: this.read,
			modify: this.modify,
			http: this.http,
			persis: this.persistence,
			triggerId,
			language,
		});

		switch (actionId) {
			case ListContextualBarEnum.REPLY_OVERFLOW_ACTIONID: {
				if (value) {
					const command = value.split(' : ')[0].trim();
					const replyId = value.split(' : ')[1].trim();

					const replyStorage = new ReplyStorage(
						this.persistence,
						persistenceRead,
					);

					const reply = await replyStorage.getReplyById(
						user,
						replyId,
					);

					if (!reply) {
						return this.context
							.getInteractionResponder()
							.errorResponse();
					}
					const language = await getUserPreferredLanguage(
						this.read.getPersistenceReader(),
						this.persistence,
						user.id,
					);
					if (room) {
						switch (command) {
							case ListContextualBarEnum.SEND:
								const sendModal = await SendReplyModal(
									this.app,
									user,
									this.read,
									this.persistence,
									this.modify,
									room,
									reply,
									language,
								);

								return this.context
									.getInteractionResponder()
									.openModalViewResponse(sendModal);

								break;
							case ListContextualBarEnum.EDIT:
								const editModal = await EditReplyModal(
									this.app,
									user,
									this.read,
									this.persistence,
									this.modify,
									room,
									reply,
									language,
								);
								return this.context
									.getInteractionResponder()
									.openModalViewResponse(editModal);

								break;
							case ListContextualBarEnum.DELETE:
								const confirmModal = await confirmDeleteModal(
									this.app,
									user,
									this.read,
									this.persistence,
									this.modify,
									room,
									reply,
									language,
								);
								return this.context
									.getInteractionResponder()
									.openModalViewResponse(confirmModal);

							default:
						}
					}
				}
				break;
			}
			case MessageActionButton.CREATE_REPLY_ACTION_ID: {
				await handler.CreateReply();
				break;
			}
			case MessageActionButton.LIST_REPLY_ACTION_ID: {
				await handler.ListReply();
				break;
			}
			case MessageActionButton.CONFIGURE_PREFERENCES_ACTION_ID:
				await handler.Configure();
				break;
			case MessageActionButton.NEED_MORE_ACTION_ID:
				await handler.Help();
				break;
			case ListContextualBarEnum.SEARCH_ACTION_ID:
				if (value) {
					const UpdatedListBar = await listReplyContextualBar(
						this.app,
						user,
						this.read,
						this.persistence,
						this.modify,
					room,
					userReplies,
					language,
					value,
					container.id,
				);
					return this.context
						.getInteractionResponder()
						.updateContextualBarViewResponse(UpdatedListBar);
				} else {
					const UpdatedListBar = await listReplyContextualBar(
						this.app,
						user,
						this.read,
						this.persistence,
						this.modify,
						room,
						userReplies,
						language,
						undefined,
						container.id,
					);
					return this.context
						.getInteractionResponder()
						.updateContextualBarViewResponse(UpdatedListBar);
				}
			case ReplyAIModalEnum.PROMPT_INPUT_ACTION_ID:
				const aistorage = new AIstorage(
					this.persistence,
					this.read.getPersistenceReader(),
					user.id,
				);
				if (value) {
					await aistorage.updatePrompt(value);
				}
				break;

			case ReplyAIModalEnum.GENERATE_BUTTON_ACTION_ID:
				const aiStorage = new AIstorage(
					this.persistence,
					this.read.getPersistenceReader(),
					user.id,
				);
				const message = await aiStorage.getMessage();
				const prompt = await aiStorage.getPrompt();

				const Preference = await userPreference.getUserPreference();

				const response = await new AIHandler(
					this.app,
					this.http,
					Preference,
				).handleResponse(message, prompt);

				await aiStorage.updateResponse(response);

				const updatedModal = await ReplyAIModal(
					this.app,
					user,
					this.read,
					this.persistence,
					this.modify,
					room,
					language,
					message,
					response,
				);

				return this.context
					.getInteractionResponder()
					.updateModalViewResponse(updatedModal);
			case UserPreferenceModalEnum.AI_PREFERENCE_DROPDOWN_ACTION_ID:
				if (value === AIusagePreferenceEnum.Personal) {
					existingPreference.AIusagePreference =
						AIusagePreferenceEnum.Personal;
					await userPreference.storeUserPreference(
						existingPreference,
					);
					const updatedPreference =
						await userPreference.getUserPreference();

					const updatedModal = await UserPreferenceModal({
						app: this.app,
						modify: this.modify,
						existingPreference: updatedPreference,
					});

					return this.context
						.getInteractionResponder()
						.updateModalViewResponse(updatedModal);
				} else {
					existingPreference.AIusagePreference =
						AIusagePreferenceEnum.Workspace;
					await userPreference.storeUserPreference(
						existingPreference,
					);
					const updatedPreference =
						await userPreference.getUserPreference();

					const updatedModal = await UserPreferenceModal({
						app: this.app,
						modify: this.modify,
						existingPreference: updatedPreference,
					});

					return this.context
						.getInteractionResponder()
						.updateModalViewResponse(updatedModal);
				}
				break;
			case UserPreferenceModalEnum.AI_OPTION_DROPDOWN_ACTION_ID:
				const option = value as AIProviderEnum;
				if (value) {
					if (Object.values(AIProviderEnum).includes(option)) {
						existingPreference.AIconfiguration.AIProvider = option;
						await userPreference.storeUserPreference(
							existingPreference,
						);
						const updatedPreference =
							await userPreference.getUserPreference();

						const updatedModal = await UserPreferenceModal({
							app: this.app,
							modify: this.modify,
							existingPreference: updatedPreference,
						});

						return this.context
							.getInteractionResponder()
							.updateModalViewResponse(updatedModal);
					} else {
						console.log('value is not part of AIProviderEnum enum');
					}
				} else {
					console.log('no value');
				}
				break;
		}

		if (actionId.startsWith(SuggestionAction.SUGGESTION_ACTION_PREFIX)) {
			if (value) {
				try {
					const { text, threadId: suggestionThreadId } =
						JSON.parse(value);
					await sendMessage(
						this.modify,
						user,
						room,
						text,
						suggestionThreadId || undefined,
					);
				} catch (e) {
					this.app
						.getLogger()
						.error(
							`Failed to send suggestion: ${e.message}`,
						);
					return this.context
						.getInteractionResponder()
						.errorResponse();
				}
			}
		}

		return this.context.getInteractionResponder().successResponse();
	}
}

import {
	IHttp,
	IModify,
	IPersistence,
	IRead,
} from '@rocket.chat/apps-engine/definition/accessors';
import {
	IUIKitResponse,
	UIKitActionButtonInteractionContext,
} from '@rocket.chat/apps-engine/definition/uikit';

import { Handler } from './Handler';
import { QuickRepliesApp } from '../../QuickRepliesApp';
import { ActionButton } from '../enum/modals/common/ActionButtons';
import { getUserPreferredLanguage } from '../helper/userPreference';
import { RoomInteractionStorage } from '../storage/RoomInteraction';
import { Receiverstorage } from '../storage/ReceiverStorage';

export class ExecuteActionButtonHandler {
	private context: UIKitActionButtonInteractionContext;
	constructor(
		protected readonly app: QuickRepliesApp,
		protected readonly read: IRead,
		protected readonly http: IHttp,
		protected readonly persistence: IPersistence,
		protected readonly modify: IModify,
		context: UIKitActionButtonInteractionContext,
	) {
		this.context = context;
	}

	public async handleActions(): Promise<IUIKitResponse> {
		const { actionId, user, room, triggerId, message } =
			this.context.getInteractionData();

		const language = await getUserPreferredLanguage(
			this.read.getPersistenceReader(),
			this.persistence,
			user.id,
		);

		const roomInteractionStorage = new RoomInteractionStorage(
			this.persistence,
			this.read.getPersistenceReader(),
			user.id,
		);
		roomInteractionStorage.storeInteractionRoomId(room.id);

		const handler = new Handler({
			app: this.app,
			sender: user,
			room: room,
			read: this.read,
			modify: this.modify,
			http: this.http,
			persis: this.persistence,
			triggerId,
			language,
		});

		switch (actionId) {
			case ActionButton.LIST_QUICK_REPLY_ACTION: {
				await handler.ListReply();
				break;
			}
			case ActionButton.CREATE_QUICK_REPLY_ACTION: {
				await handler.CreateReply();
				break;
			}
		}

		const hasTextOrAttachments =
			(message?.text || message?.attachments) && actionId;

		if (hasTextOrAttachments) {
			const textMessage =
				message?.text || message?.attachments?.[0]?.description || '';

			if (!textMessage.trim()) {
				return this.context.getInteractionResponder().errorResponse();
			}

			switch (actionId) {
				case ActionButton.REPLY_USING_AI_ACTION: {
					await handler.replyUsingAI(textMessage.trim());
					break;
				}
				case ActionButton.SEND_REPLY_ACTION: {
					const PlaceHolderValues = {
						room: message.room.slugifiedName,
						username: message.sender.username,
						name: message.sender.name,
						email: message.sender?.emails[0]?.address,
					};
					const ReceiverStorage = new Receiverstorage(
						this.persistence,
						this.read.getPersistenceReader(),
						user.id,
					);
					await ReceiverStorage.setReceiverRecord(PlaceHolderValues);

					await handler.ListReply();
					break;
				}
				default: {
					console.log('Unhandled actionId:', actionId);
				}
			}
		}

		return this.context.getInteractionResponder().successResponse();
	}
}

export interface IRoomInteractionStorage {
	storeInteractionRoomId(roomId: string): Promise<void>;
	getInteractionRoomId(): Promise<string | undefined>;
	clearInteractionRoomId(): Promise<void>;
}

import {
	IPersistence,
	IPersistenceRead,
} from '@rocket.chat/apps-engine/definition/accessors';
import {
	RocketChatAssociationModel,
	RocketChatAssociationRecord,
} from '@rocket.chat/apps-engine/definition/metadata';
import { IUser } from '@rocket.chat/apps-engine/definition/users';
import { IReply } from '../definition/reply/IReply';
import { Language, t } from '../lib/Translation/translation';

export class ReplyStorage {
	constructor(
		private readonly persistence: IPersistence,
		private readonly persistenceRead: IPersistenceRead,
	) {}

	private createUniqueId(userId: string): string {
		const timestamp = Date.now().toString(36);
		return `${userId}-${timestamp}`;
	}

	// Validates the name and body of the reply
	private validateReply(
		name: string,
		body: string,
		language: Language,
	): { success: boolean; error?: string } {
		if (!name && !body) {
			return {
				success: false,
				error: t('Error_Fill_Fields', language),
			};
		}

		const isNameValid =
			typeof name === 'string' &&
			name.trim().length > 0 &&
			name.length <= 100;
		const isBodyValid =
			typeof body === 'string' &&
			body.trim().length > 0 &&
			body.length <= 1000;

		if (!isNameValid) {
			return {
				success: false,
				error: t('Error_Reply_Name_Invalid', language),
			};
		}

		if (!isBodyValid) {
			return {
				success: false,
				error: t('Error_Reply_Body_Invalid', language),
			};
		}

		return { success: true };
	}

	// Checks if the reply name is unique for the user
	private async isUniqueReplyName(
		user: IUser,
		name: string,
		replyId?: string,
	): Promise<boolean> {
		const replies = await this.getReplyForUser(user);

		const replyFound = replies.find((reply) => reply.name === name);
		if (replyFound && replyId) {
			return replyFound.id === replyId;
		} else if (replyFound) {
			return false;
		}
		return true;
	}

	private getAssociations(userId: string): RocketChatAssociationRecord[] {
		return [
			new RocketChatAssociationRecord(
				RocketChatAssociationModel.USER,
				userId,
			),
			new RocketChatAssociationRecord(
				RocketChatAssociationModel.MISC,
				'reply',
			),
		];
	}

	// Creates a new reply and stores it
	public async createReply(
		user: IUser,
		name: string,
		body: string,
		language: Language,
	): Promise<{ success: boolean; error?: string }> {
		const validation = this.validateReply(name, body, language);

		if (!validation.success) {
			return validation;
		}

		try {
			if (!(await this.isUniqueReplyName(user, name))) {
				return {
					success: false,
					error: t('Error_Reply_Name_Already_Exists', language),
				};
			}

			const association = this.getAssociations(user.id);
			const userPrevReply: IReply[] = await this.getReplyForUser(user);

			userPrevReply.push({
				id: this.createUniqueId(user.id),
				name,
				body,
			});

			await this.persistence.updateByAssociations(
				association,
				userPrevReply,
				true,
			);
			return { success: true };
		} catch (error) {
			console.warn('Create Reply Error: ', error);
			return {
				success: false,
				error: t('Error_Fail_Internal', language),
			};
		}
	}

	public async getReplyForUser(user: IUser): Promise<IReply[]> {
		try {
			const associations = this.getAssociations(user.id);
			const reply = await this.persistenceRead.readByAssociations(
				associations,
			);
			return reply && reply.length ? (reply[0] as IReply[]) : [];
		} catch (error) {
			console.warn('Get Reply Error:', error);
			return [];
		}
	}

	public async getReplyById(
		user: IUser,
		replyId: string,
	): Promise<IReply | null> {
		const userReplies = await this.getReplyForUser(user);
		return userReplies.find((reply) => reply.id === replyId) || null;
	}

	public async updateReplyById(
		user: IUser,
		replyId: string,
		name: string,
		body: string,
		language: Language,
	): Promise<{ success: boolean; error?: string }> {
		const validation = this.validateReply(name, body, language);

		if (!validation.success) {
			return validation;
		}

		try {
			if (!(await this.isUniqueReplyName(user, name, replyId))) {
				return {
					success: false,
					error: t('Error_Reply_Name_Already_Exists', language),
				};
			}

			const userReplies = await this.getReplyForUser(user);
			const replyIndex = userReplies.findIndex(
				(reply) => reply.id === replyId,
			);

			if (replyIndex === -1) {
				return {
					success: false,
					error: t('Error_Reply_Not_Found', language),
				};
			}

			userReplies[replyIndex] = { id: replyId, name, body };

			const association = this.getAssociations(user.id);
			await this.persistence.updateByAssociations(
				association,
				userReplies,
				true,
			);
			return { success: true };
		} catch (error) {
			console.warn('Update Reply Error: ', error);
			return {
				success: false,
				error: t('Error_Fail_Internal', language),
			};
		}
	}

	public async deleteReplyById(
		user: IUser,
		replyId: string,
		language: Language,
	): Promise<{ success: boolean; error?: string }> {
		try {
			const userReplies = await this.getReplyForUser(user);
			const replyIndex = userReplies.findIndex(
				(reply) => reply.id === replyId,
			);

			if (replyIndex === -1) {
				return {
					success: false,
					error: t('Error_Reply_Not_Found', language),
				};
			}

			userReplies.splice(replyIndex, 1);

			const association = this.getAssociations(user.id);
			await this.persistence.updateByAssociations(
				association,
				userReplies,
				true,
			);
			return { success: true };
		} catch (error) {
			console.warn('Delete Reply Error: ', error);
			return {
				success: false,
				error: t('Error_Fail_Internal', language),
			};
		}
	}
}

import {
	RocketChatAssociationModel,
	RocketChatAssociationRecord,
} from '@rocket.chat/apps-engine/definition/metadata';
import {
	IPersistence,
	IPersistenceRead,
} from '@rocket.chat/apps-engine/definition/accessors';
import { IAIstorage } from '../definition/lib/IAIstorage';

export class AIstorage implements IAIstorage {
	private userId: string;
	constructor(
		private readonly persistence: IPersistence,
		private readonly persistenceRead: IPersistenceRead,
		userId: string,
	) {
		this.userId = userId;
	}

	private async getInteractionRecord(): Promise<{
		prompt: string;
		response: string;
		message: string;
	}> {
		const association = new RocketChatAssociationRecord(
			RocketChatAssociationModel.USER,
			`${this.userId}#AIinteraction`,
		);
		const [result] = (await this.persistenceRead.readByAssociation(
			association,
		)) as Array<{ prompt: string; response: string; message: string }>;
		return result || { prompt: '', response: '', message: '' };
	}

	private async storeInteractionRecord(record: {
		prompt: string;
		response: string;
		message: string;
	}): Promise<void> {
		const association = new RocketChatAssociationRecord(
			RocketChatAssociationModel.USER,
			`${this.userId}#AIinteraction`,
		);
		await this.persistence.updateByAssociation(association, record, true);
